// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// SystemClock is the default Clock backed by time.Now.
var SystemClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds at most Burst tokens and is refilled at Rate tokens per second.
// A Limiter must be created via NewLimiter; the zero value is not usable.
type Limiter struct {
	mu       sync.Mutex
	burst    int
	rate     float64 // tokens per second
	tokens   float64
	lastTime time.Time
	clock    Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// NewLimiter returns a Limiter that starts full with burst tokens and refills
// at rate tokens per second. rate and burst must be positive and clock must
// not be nil.
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		burst:    burst,
		rate:     rate,
		tokens:   float64(burst),
		lastTime: clock.Now(),
		clock:    clock,
	}, nil
}

// advance refills tokens based on elapsed time since lastTime.
// Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.lastTime = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are deducted; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// RetryAfter returns the duration until n tokens would be available at time
// now, or 0 if n tokens are available now. It returns an error for invalid n.
func (l *Limiter) RetryAfter(now time.Time, n int) (time.Duration, error) {
	if n < 0 {
		return 0, fmt.Errorf("ratelimit: n must be >= 0, got %d", n)
	}
	if n > l.burst {
		return 0, fmt.Errorf("ratelimit: n=%d exceeds burst=%d", n, l.burst)
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	deficit := float64(n) - l.tokens
	if deficit <= 0 {
		return 0, nil
	}
	return time.Duration(deficit / l.rate * float64(time.Second)), nil
}
