// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created with New; the zero value is not usable.
type Limiter struct {
	mu        sync.Mutex
	clock     Clock
	rate      float64 // tokens per second
	burst     float64 // bucket capacity
	tokens    float64
	lastRefil time.Time
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New returns a Limiter that refills rate tokens per second, with a
// maximum capacity of burst tokens. The bucket starts full.
// If clock is nil, the real system clock is used.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		clock:     clock,
		rate:      rate,
		burst:     float64(burst),
		tokens:    float64(burst),
		lastRefil: now,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at time now,
// consuming them if so. n must be positive; AllowN returns false
// for n <= 0 without consuming tokens.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastRefil).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastRefil = now
	}

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
