// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock reports the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock is the default Clock backed by time.Now.
var SystemClock Clock = systemClock{}

// Limiter is a token-bucket rate limiter. The zero value is not usable;
// construct one with New. A Limiter is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	capacity float64
	rate     float64 // tokens per second
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive capacity or rate.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// New returns a full Limiter with the given burst capacity and refill rate
// (tokens per second). Both must be positive.
func New(capacity, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, SystemClock)
}

// NewWithClock is like New but uses the provided Clock.
func NewWithClock(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || math.IsNaN(capacity) || math.IsInf(capacity, 0) {
		return nil, ErrInvalidConfig
	}
	if rate <= 0 || math.IsNaN(rate) || math.IsInf(rate, 0) {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = SystemClock
	}
	now := clock.Now()
	return &Limiter{
		tokens:   capacity,
		last:     now,
		capacity: capacity,
		rate:     rate,
		clock:    clock,
	}, nil
}

// advance refills tokens up to now. Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = math.Min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now. If allowed,
// the tokens are consumed; otherwise the bucket is left unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(l.clock.Now(), 1) }

// Tokens returns the number of tokens currently available (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}
